import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"架构","description":"","frontmatter":{},"headers":[],"relativePath":"zh/architecture.md","filePath":"zh/architecture.md"}`),a={name:`zh/architecture.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to “架构”">​</a></h1><p>FaultDeck 是一个 Rust workspace。当前实现包含 <strong>6 个已构建 crate</strong>,外加一个空占位(<code>faultdeck-protocol</code> —— 目录存在,但没有 <code>Cargo.toml</code>,<strong>尚未加入 workspace</strong>)。<a href="/faultdeck/zh/design/mvp-plan.html">MVP 计划</a>中的 toxiproxy 后端与场景 YAML DSL 尚未实现;如今的实现后端是 <code>tc netem</code> + <code>iptables</code>。</p><h2 id="crate-一览" tabindex="-1">Crate 一览 <a class="header-anchor" href="#crate-一览" aria-label="Permalink to “Crate 一览”">​</a></h2><table tabindex="0"><thead><tr><th>crate</th><th>二进制</th><th>职责</th></tr></thead><tbody><tr><td><code>faultdeck-core</code></td><td>—</td><td>共享模型:<code>FaultSpec</code>(latency / loss / disconnect)、<code>Target</code>、<code>Injection</code>、内在校验(<code>validate_injection</code>)、管理网段重叠检查</td></tr><tr><td><code>faultdeck-netem</code></td><td>—</td><td><code>tc</code> 适配器:规划并执行 <code>tc qdisc</code>/<code>filter</code> 命令,preflight 检查,回滚,<code>dry_run</code> 执行器</td></tr><tr><td><code>faultdeck-agent</code></td><td><code>faultdeck-agent</code></td><td>常驻 TCP 守护进程:token 鉴权、请求处理、iptables 防火墙(disconnect)、单故障状态</td></tr><tr><td><code>faultdeck-coordinator</code></td><td><code>faultdeck-coordinator</code></td><td>多目标中枢:agent 注册表(register/heartbeat/list)、报告归档、排队中的 inject/rollback 命令</td></tr><tr><td><code>faultdeck-report</code></td><td>—</td><td><code>Scenario</code>、<code>RunReport</code>(JSON/HTML)、SHA-256 场景哈希、<code>compare_runs</code> 历史 diff</td></tr><tr><td><code>faultdeck-cli</code></td><td><code>faultdeck</code></td><td>CLI 入口:<code>faultdeck remote ping / inject / rollback</code></td></tr><tr><td><code>faultdeck-protocol</code></td><td>—</td><td><em>占位,不在 workspace 中</em></td></tr></tbody></table><h2 id="交互总览" tabindex="-1">交互总览 <a class="header-anchor" href="#交互总览" aria-label="Permalink to “交互总览”">​</a></h2><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> faultdeck CLI                faultdeck-agent                目标主机</span></span>
<span class="line"><span> ┌──────────────┐  TCP 换行   ┌──────────────────┐   tc      ┌──────────┐</span></span>
<span class="line"><span> │ remote ping  │  分帧 JSON  │ token 鉴权        │──qdisc──▶ │  eth0    │</span></span>
<span class="line"><span> │ remote inject│             │ 管理网段守卫       │──filter─▶ │ (netem)  │</span></span>
<span class="line"><span> │ remote       │             │ validate_injection│           └──────────┘</span></span>
<span class="line"><span> │   rollback   │             │                  │  iptables ┌──────────┐</span></span>
<span class="line"><span> └──────────────┘             │ firewall (mangle)│──DROP────▶│ disconnect│</span></span>
<span class="line"><span>                              └──────────────────┘  -t mangle└──────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span> faultdeck-coordinator(默认 :7001)</span></span>
<span class="line"><span> ┌────────────────────────────────────────────┐</span></span>
<span class="line"><span> │ 注册表: agents / reports / routes           │◀── 换行分帧 JSON(多消息长连接,</span></span>
<span class="line"><span> │ AgentCommand: register, heartbeat,         │    线程化 accept)</span></span>
<span class="line"><span> │   inject, rollback, fetch_report,          │</span></span>
<span class="line"><span> │   list_agents                              │</span></span>
<span class="line"><span> └────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="线协议-cli-↔-agent" tabindex="-1">线协议(CLI ↔ agent) <a class="header-anchor" href="#线协议-cli-↔-agent" aria-label="Permalink to “线协议(CLI ↔ agent)”">​</a></h2><p>每次 CLI 调用一条 TCP 连接。客户端发一行,agent 应答一行 JSON 后关闭。</p><ul><li>带 token:<code>&lt;token&gt; {json}\\n</code> —— 不带:<code>{json}\\n</code></li><li>请求:<code>{&quot;cmd&quot;:&quot;ping&quot;}</code> | <code>{&quot;cmd&quot;:&quot;inject&quot;, …Injection}</code> | <code>{&quot;cmd&quot;:&quot;rollback&quot;}</code></li><li>响应:<code>{&quot;status&quot;:&quot;ok&quot;,&quot;message&quot;:&quot;…&quot;}</code> | <code>{&quot;status&quot;:&quot;error&quot;,&quot;message&quot;:&quot;…&quot;}</code></li></ul><h2 id="线协议-coordinator" tabindex="-1">线协议(coordinator) <a class="header-anchor" href="#线协议-coordinator" aria-label="Permalink to “线协议(coordinator)”">​</a></h2><p>长连接,双向按行分帧的 JSON(<code>faultdeck-agent::transport</code>)。标签枚举:</p><ul><li><code>AgentCommand</code>:<code>register</code> | <code>heartbeat</code> | <code>inject</code> | <code>rollback</code> | <code>fetch_report</code> | <code>list_agents</code></li><li><code>AgentResponse</code>:<code>ok</code> | <code>error</code> | <code>registered</code> | <code>agents</code> | <code>report</code></li></ul><p>状态保存在 <code>Mutex&lt;CoordinatorState&gt;</code>:<code>agents</code>、<code>reports</code> 为 <code>BTreeMap</code>,另有 <code>routes</code> 映射。</p><p><strong>实现状态:</strong> coordinator 的 <code>inject</code>/<code>rollback</code> 目前只是<strong>入队</strong>(响应为 <code>queued for {id}</code>,并按场景哈希归档一份报告桩)。向在线 agent 连接的分发尚未接线;<code>register</code>/<code>heartbeat</code>/<code>list_agents</code>/<code>fetch_report</code> 在进程内已完整可用。</p><h2 id="netem-适配器的失败处理" tabindex="-1">netem 适配器的失败处理 <a class="header-anchor" href="#netem-适配器的失败处理" aria-label="Permalink to “netem 适配器的失败处理”">​</a></h2><ol><li><code>plan()</code> 只校验并返回命令列表,不执行。</li><li><code>inject()</code> 先跑 preflight <code>tc qdisc show</code> —— 若网卡根 qdisc 不是 FaultDeck 的 <code>100:</code> 句柄,拒绝操作。</li><li>应用前先清理上一次运行遗留的 FaultDeck 根 qdisc。</li><li>应用过程中任何命令失败,适配器立即下发回滚命令。</li><li><code>rollback()</code> 删除根 qdisc;<code>tc</code> 的「找不到」类错误按已清理处理(幂等)。</li></ol><p>disconnect 故障完全绕过 <code>tc</code> —— 见 <a href="/faultdeck/zh/netem-faults.html#disconnect">Netem 故障</a>。</p>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};